mod solution;

fn main() {
    let cases = [
    (r#"[[1,2,3],[4,5,6],[7,8,9]]"#, r#"24"#),
    (r#"[[0,0],[1,2],[3,4]]"#, r#"10"#),
    (r#"
[[0,0],[1,2],[3,4]]
"#, r#"10"#),
    (r#"  
[[1,2,3],[4,5,6],[7,8,9]]
  "#, r#"24"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS prefix-sum-2d");
}
